<?php
namespace App\Models;
use App\Domain\ServiceOrders\Enums\ServiceOrderStatus;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class ServiceOrder extends Model { use SoftDeletes; protected $fillable=['number','customer_id','commercial_quote_id','status','maintenance_type','description','service_location','contact_name','contact_phone','customer_snapshot','execution_snapshot','started_at','completed_at','closed_at','closed_by','closed_pdf_path','closed_pdf_hash']; protected function casts():array{return ['status'=>ServiceOrderStatus::class,'customer_snapshot'=>'array','execution_snapshot'=>'array','started_at'=>'datetime','completed_at'=>'datetime','closed_at'=>'datetime'];} public function customer():BelongsTo{return $this->belongsTo(ServiceCustomer::class);} public function commercialQuote():BelongsTo{return $this->belongsTo(CommercialQuote::class);} public function assignments():HasMany{return $this->hasMany(ServiceOrderAssignment::class);} public function activities():HasMany{return $this->hasMany(ServiceOrderActivity::class);} public function equipments():HasMany{return $this->hasMany(ServiceOrderEquipment::class);} public function materials():HasMany{return $this->hasMany(ServiceOrderMaterial::class);} public function evidences():HasMany{return $this->hasMany(ServiceOrderEvidence::class);} public function signatures():HasMany{return $this->hasMany(ServiceOrderSignature::class);} public function events():HasMany{return $this->hasMany(ServiceOrderEvent::class);} public function closed():bool{return $this->status===ServiceOrderStatus::Closed;} }
